const maxAge = 60, swr = 300;
const timeline = [0, 30, 75, 90, 200, 400, 410];
let storedAt = 0;
let version = 1;
let pendingFresh = false;
function value(v) { return 'v' + v; }
function handle(now) {
  const age = now - storedAt;
  let served, refetch;
  if (pendingFresh) { version++; storedAt = now; pendingFresh = false; served = value(version); refetch = false; }
  else if (age <= maxAge) { served = value(version); refetch = false; }
  else if (age <= maxAge + swr) { served = value(version); refetch = true; pendingFresh = true; }
  else { version++; storedAt = now; served = value(version); refetch = true; }
  console.log('t=' + now + ' served=' + served + ' refetch=' + (refetch ? 'yes' : 'no'));
}
for (const now of timeline) handle(now);
